com.mirth.connect.plugins.javascriptstep.script:
// Converts the inbound ORU^R01 message's PID/PV1/OBX segments into the JSON
// array LCIIS's POST /api/lab-result endpoint expects. Equivalent logic to
// hl7/hl7_parser.py, used when running the standalone MLLP bridge instead.

var patientId = msg['PID']['PID.3']['PID.3.1'].toString();
var lastName = msg['PID']['PID.5']['PID.5.1'].toString();
var firstName = msg['PID']['PID.5']['PID.5.2'].toString();
var patientName = (firstName + ' ' + lastName).trim() || patientId;

var ward = msg['PV1']['PV1.3']['PV1.3.1'].toString();
var bed = msg['PV1']['PV1.3']['PV1.3.2'].toString();

var doctorFamily = msg['PV1']['PV1.7']['PV1.7.2'].toString();
var doctorGiven = msg['PV1']['PV1.7']['PV1.7.3'].toString();
var physician = doctorFamily ? ('Dr. ' + doctorFamily + ' ' + doctorGiven).trim() : null;

function formatHl7Timestamp(ts) {
    if (!ts || ts.length < 8) { return new Date().toISOString(); }
    var y = ts.substring(0, 4), mo = ts.substring(4, 6), d = ts.substring(6, 8);
    var h = ts.length >= 10 ? ts.substring(8, 10) : '00';
    var mi = ts.length >= 12 ? ts.substring(10, 12) : '00';
    var s = ts.length >= 14 ? ts.substring(12, 14) : '00';
    return y + '-' + mo + '-' + d + 'T' + h + ':' + mi + ':' + s;
}

var results = [];
var obxCount = msg['OBX'].length();
for (var i = 0; i < obxCount; i++) {
    var obx = msg['OBX'][i];
    var code = obx['OBX.3']['OBX.3.1'].toString();
    var name = obx['OBX.3']['OBX.3.2'].toString() || code;
    var value = parseFloat(obx['OBX.5']['OBX.5.1'].toString());
    if (isNaN(value)) { continue; } // skip free-text / non-numeric OBX rows

    var unit = obx['OBX.6']['OBX.6.1'].toString() || null;
    var refRange = obx['OBX.7'].toString();
    var refLow = null, refHigh = null;
    if (refRange.indexOf('-') > -1) {
        var parts = refRange.split('-');
        refLow = parseFloat(parts[0]);
        refHigh = parseFloat(parts[1]);
    }

    var observedAt = obx['OBX.14']['OBX.14.1'].toString() ||
                      msg['OBR']['OBR.7']['OBR.7.1'].toString();

    results.push({
        patient_id: patientId,
        patient_name: patientName,
        bed: bed || null,
        ward: ward || null,
        test_code: code,
        test_name: name,
        value: value,
        unit: unit,
        ref_low: isNaN(refLow) ? null : refLow,
        ref_high: isNaN(refHigh) ? null : refHigh,
        ordering_physician: physician,
        collected_at: formatHl7Timestamp(observedAt)
    });
}

channelMap.put('labResultPayloads', JSON.stringify(results));

com.mirth.connect.plugins.javascriptrule.script:
var messageType = msg['MSH']['MSH.9']['MSH.9.1'].toString();
var triggerEvent = msg['MSH']['MSH.9']['MSH.9.2'].toString();
return (messageType == 'ORU' && triggerEvent == 'R01');

properties.script:
// Posts one HTTP request per OBX-derived lab result to the LCIIS backend.
// The API base URL is read from the Configuration Map key LCIIS_API_URL
// (Mirth Administrator > Settings > Configuration Map) so it doesn't need
// to be hardcoded per environment; falls back to localhost for dev.

importPackage(java.net);
importPackage(java.io);

var apiBaseUrl = configurationMap.get('LCIIS_API_URL');
if (!apiBaseUrl) { apiBaseUrl = 'http://localhost:8000'; }

var payloadsJson = channelMap.get('labResultPayloads');
var payloads = JSON.parse(payloadsJson);

var results = [];
for (var i = 0; i < payloads.length; i++) {
    var payload = payloads[i];
    var url = new URL(apiBaseUrl + '/api/lab-result');
    var conn = url.openConnection();
    conn.setRequestMethod('POST');
    conn.setDoOutput(true);
    conn.setRequestProperty('Content-Type', 'application/json');
    conn.setConnectTimeout(10000);
    conn.setReadTimeout(10000);

    var body = JSON.stringify(payload);
    var out = conn.getOutputStream();
    out.write(java.lang.String(body).getBytes('UTF-8'));
    out.flush();
    out.close();

    var status = conn.getResponseCode();
    if (status >= 400) {
        var stream = conn.getErrorStream();
        var errText = '';
        if (stream != null) {
            var scanner = new java.util.Scanner(stream, 'UTF-8').useDelimiter('\\A');
            errText = scanner.hasNext() ? scanner.next() : '';
        }
        throw 'LCIIS API returned HTTP ' + status + ' for ' + payload.test_code +
              ' (' + payload.patient_id + '): ' + errText;
    }
    results.push(payload.test_code + '=' + status);
    conn.disconnect();
}

return 'Posted ' + results.length + ' result(s): ' + results.join(', ');
